{"content": "#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Full industry x device-block cross-tab for 基102-2002 + check Table D.1 for 燃气轮机."""
import openpyxl, os
from collections import Counter

base = "/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/04_实验C_规模与资源表现/050%规模/01_工业锅炉/03_通用工具调用型Agent/R2/inputs"
p = os.path.join(base, "基102-2002_原始结构脱敏输入.xlsx")
wb = openpyxl.load_workbook(p, read_only=True, data_only=True)
ws = wb["Sheet1"]
rows = list(ws.iter_rows(values_only=True))
hdr = rows[0]
data = rows[1:]
H = {n: i for i, n in enumerate(hdr)}
def get(r, name):
    i = H.get(name)
    return r[i] if i is not None else None
def filled(r, name):
    v = get(r, name)
    return v is not None and str(v).strip() != ""

# classify industry sector
def sector(code):
    s = str(code)
    if not s.isdigit():
        return "UNKNOWN:" + s
    c = int(s[:2])
    if 6 <= c <= 12:
        return "B06-12 采矿业"
    if 13 <= c <= 43:
        return "C13-43 制造业"
    if s.startswith("45"):
        return "D45 燃气生产和供应业"
    if s in ("4411", "4412", "4417", "4430"):
        return "D44 电力热力(标准范围)"
    if s.startswith("44"):
        return "D44 其他电力(4419等)"
    if s.startswith("46") or s.startswith("47"):
        return "D46-47 水电气"
    if s.startswith("48") or s.startswith("49"):
        return "E 建筑"
    if s.startswith("51") or s.startswith("52"):
        return "F 批发零售"
    if s.startswith("53") or s.startswith("59"):
        return "G 交通运输"
    if s.startswith("61") or s.startswith("62"):
        return "H 住宿餐饮"
    if s.startswith("63") or s.startswith("69"):
        return "I 信息软件"
    if s.startswith("70") or s.startswith("72"):
        return "K 房地产/租赁"
    if s.startswith("73") or s.startswith("75"):
        return "M 科研技术"
    if s.startswith("76") or s.startswith("79"):
        return "N 水利环境公共"
    return "OTHER:" + s[:2]

print("--- ind-block devices by sector ---")
c = Counter()
for r in data:
    if filled(r, "工业锅炉编号"):
        c[sector(get(r, "行业类别代码"))] += 1
for k, v in c.most_common():
    print(k, v)

print("\n--- power-block devices by sector ---")
c = Counter()
for r in data:
    if filled(r, "电站锅炉/燃气轮机编号"):
        c[sector(get(r, "行业类别代码"))] += 1
for k, v in c.most_common():
    print(k, v)

print("\n--- ind-block devices in D44 industries (should be rare) ---")
for r in data:
    if filled(r, "工业锅炉编号") and str(get(r, "行业类别代码")).startswith("44"):
        print(get(r, "行业类别代码"), get(r, "行业类别名称"), "| ind type:", get(r, "工业锅炉类型"), "| f1:", get(r, "燃料一类型"), get(r, "燃料一消耗量"))

print("\n--- ind-block devices in non-B/C/D sectors (OUT_OF_SCOPE candidates) ---")
for r in data:
    if filled(r, "工业锅炉编号") and sector(get(r, "行业类别代码")).startswith(("D44", "D46", "E ", "F ", "G ", "H ", "I ", "K ", "M ", "N ", "OTHER", "UNKNOWN")):
        print(get(r, "行业类别代码"), get(r, "行业类别名称"), "| ind type:", get(r, "工业锅炉类型"), "| f1:", get(r, "燃料一类型"), get(r, "燃料一消耗量"))

print("\n--- power-block devices in B/C/D (non-D44) industries (self-supply power) ---")
c = Counter()
for r in data:
    if filled(r, "电站锅炉/燃气轮机编号"):
        sec = sector(get(r, "行业类别代码"))
        if sec.startswith(("B0", "C1", "D45")):
            c[(get(r, "行业类别代码"), get(r, "行业类别名称"), get(r, "电站锅炉/燃气轮机类型"))] += 1
for k, v in c.most_common():
    print(k, v)

wb.close()
