{"content": "#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Quantify data-quality edge cases for the build."""
import openpyxl, os
from collections import Counter

base = "/Users/wushuo/Desktop/环境学院论文/固定燃烧源清单经验缺失处置实验/实验结果/04_实验C_规模与资源表现/050%规模/01_工业锅炉/03_通用工具调用型Agent/R2/inputs"
p = os.path.join(base, "基102-2002_原始结构脱敏输入.xlsx")
wb = openpyxl.load_workbook(p, read_only=True, data_only=True)
ws = wb["Sheet1"]
rows = list(ws.iter_rows(values_only=True))
hdr = rows[0]
data = rows[1:]
H = {n: i for i, n in enumerate(hdr)}
def get(r, name):
    i = H.get(name)
    return r[i] if i is not None else None
def filled(r, name):
    v = get(r, name)
    return v is not None and str(v).strip() != ""

def num(v):
    if v is None:
        return None
    s = str(v).strip()
    if s == "":
        return None
    try:
        return float(s)
    except ValueError:
        return None

# coal rows: fuel1 coal types with 燃烧方式
coal_types = {"一般烟煤", "无烟煤", "原煤", "褐煤", "煤制品"}
print("--- industrial coal rows: fuel1 coal x 燃烧方式 ---")
c = Counter()
coal_rows = []
for r in data:
    if filled(r, "工业锅炉编号") and get(r, "燃料一类型") in coal_types:
        c[(get(r, "燃料一类型"), get(r, "工业锅炉燃烧方式"))] += 1
        coal_rows.append(r)
for k, v in c.most_common():
    print(k, v)
print("total industrial coal rows:", len(coal_rows))

print("\n--- industrial coal rows: 含硫量/灰分 availability ---")
c = Counter()
for r in coal_rows:
    c[("S", filled(r, "燃料一平均收到基含硫量"), "ash", filled(r, "燃料一平均收到基灰分（%）"))] += 1
for k, v in c.most_common():
    print(k, v)

print("\n--- industrial coal rows: S unit / ash value sample ---")
for r in coal_rows[:8]:
    print(get(r, "燃料一类型"), "| 燃烧方式:", get(r, "工业锅炉燃烧方式"),
          "| S:", get(r, "燃料一平均收到基含硫量"), get(r, "燃料一平均收到基含硫量单位"),
          "| 灰分:", get(r, "燃料一平均收到基灰分（%）"),
          "| 消耗:", get(r, "燃料一消耗量"), get(r, "燃料一消耗量单位"))

print("\n--- fuel1 consumption zero vs blank (industrial) ---")
c = Counter()
zero_rows = []
for r in data:
    if filled(r, "工业锅炉编号"):
        v = num(get(r, "燃料一消耗量"))
        if v is None:
            c["blank"] += 1
        elif v == 0:
            c["zero"] += 1
            zero_rows.append(r)
        else:
            c["positive"] += 1
print(c)
print("zero-consumption industrial rows sample:")
for r in zero_rows[:12]:
    print(get(r, "行业类别代码"), get(r, "行业类别名称"), "| type:", get(r, "工业锅炉类型"),
          "| f1:", get(r, "燃料一类型"), get(r, "燃料一消耗量"), "| f2:", get(r, "燃料二类型"), get(r, "燃料二消耗量"))

print("\n--- negative consumption? ---")
neg = [r for r in data if (num(get(r, "燃料一消耗量")) is not None and num(get(r, "燃料一消耗量")) < 0) or
       (num(get(r, "燃料二消耗量")) is not None and num(get(r, "燃料二消耗量")) < 0)]
print("rows with negative fuel consumption:", len(neg))
for r in neg[:10]:
    print(get(r, "行业类别代码"), "| f1:", get(r, "燃料一类型"), get(r, "燃料一消耗量"), "| f2:", get(r, "燃料二类型"), get(r, "燃料二消耗量"))

print("\n--- industrial rows with fuel1 type but blank consumption ---")
c = Counter()
for r in data:
    if filled(r, "工业锅炉编号") and filled(r, "燃料一类型") and not filled(r, "燃料一消耗量"):
        c[(get(r, "燃料一类型"), get(r, "燃料一消耗量单位"))] += 1
print(c)

print("\n--- other_tce > 0 (industrial) ---")
c = []
for r in data:
    if filled(r, "工业锅炉编号"):
        v = num(get(r, "其他燃料消耗总量（吨标准煤）"))
        if v is not None and v > 0:
            c.append((get(r, "行业类别代码"), get(r, "行业类别名称"), get(r, "燃料一类型"), get(r, "燃料一消耗量"), v))
for x in c[:20]:
    print(x)
print("count:", len(c))

print("\n--- 煤矸石/垃圾/工业废料 rows by block ---")
for ft in ["煤矸石（用于燃料）", "城市生活垃圾（用于燃料）", "工业废料（用于燃料）"]:
    c = Counter()
    for r in data:
        if get(r, "燃料一类型") == ft or get(r, "燃料二类型") == ft:
            block = "POWER" if filled(r, "电站锅炉/燃气轮机编号") else "IND"
            c[block] += 1
    print(ft, dict(c))

print("\n--- industrial R7 燃气轮机 rows details ---")
for r in data:
    if filled(r, "工业锅炉编号") and get(r, "工业锅炉类型代码") == "R7":
        print(get(r, "行业类别代码"), get(r, "行业类别名称"), "| 用途:", get(r, "工业锅炉用途"),
              "| 额定出力:", get(r, "工业锅炉额定出力（蒸吨/小时）"), "| 运行时间:", get(r, "工业锅炉运行时间（小时）"),
              "| 低氮:", get(r, "是否采用低氮燃烧技术"), "| f1:", get(r, "燃料一类型"), get(r, "燃料一消耗量"))

wb.close()
