def load_sheet(path):
    wb = openpyxl.load_workbook(path, read_only=True, data_only=True)
    ws = wb["Sheet1"]
    rows = list(ws.iter_rows(values_only=True))
    wb.close()
    return rows[0], rows[1:]


def num(v):
    if v is None:
        return None
    s = str(v).strip()
    if s == "":
        return None
    try:
        return float(s)
    except ValueError:
        return None


def col_index(hdr, name, occurrence=0):
    """返回第 occurrence(0起) 个匹配列名（用于重名列，如低氮燃烧技术）"""
    hits = [i for i, n in enumerate(hdr) if n == name]
    if occurrence < len(hits):
        return hits[occurrence]
    return None


