def desulf_a1_keys(p):
    keys = []
    if "炉内" in p:
        keys.append("炉内喷钙法")
    if "双碱" in p:
        keys.append("双碱法")
    elif "石灰" in p:
        keys.append("石灰石/石膏法")
    elif "钠碱" in p or "S12" in p:
        keys.append("其他脱硫技术")
    elif "海水" in p:
        keys.append("海水法")
    elif "氧化镁" in p:
        keys.append("氧化镁法")
    elif "氨法" in p:
        keys.append("氨法")
    elif "流化床" in p:
        keys.append("烟气循环流化床法")
    elif "密相干" in p:
        keys.append("密相干法")
    elif "喷雾" in p:
        keys.append("旋转喷雾干燥法")
    if not keys:
        keys.append("其他脱硫技术")
    return keys


def facility_contributions(gygl):
    """返回 (so2_effs, nox_effs, pm_fine_effs, pm_coarse_effs, no_eff_notes)
    已填报去除效率的设施：主控污染物用填报值；交叉污染物协同去除按表A.1默认。
    未填报效率的设施：主控污染物按处理工艺取表A.1默认；工艺也无法映射则记入 no_eff_notes。
    """
    so2, nox, pmf, pmc = [], [], [], []
    notes = []
    has_lnb_process = False
    for f in gygl:
        cat = g2(f, "废气治理设施名称")
        proc = g2(f, "处理工艺名称")
        rep = num(g2(f, "去除效率（%）"))
        p = str(proc).strip() if proc else ""
        if cat == "脱硫（酸）设施":
            keys = desulf_a1_keys(p) if p else ["其他脱硫技术"]
            if rep is not None:
                so2.append(min(rep, 100.0))
            else:
                for k in keys:
                    so2.append(A1[k]["SO2"])
            for k in keys:
                if k in WET_FGD_KEYS:
                    pmf.append(A1[k]["PM25"])
                    pmc.append(A1[k]["PM10c"])
        elif cat == "脱硝设施":
            a1k = PROCESS_TO_A1_DENIT.get(p) if p else None
            if rep is not None:
                nox.append(min(rep, 100.0))
            elif a1k is not None:
                nox.append(A1[a1k]["NOx"])
            else:
                nox.append(A1["其他脱硝技术"]["NOx"])
            if a1k in SCR_KEYS:
                pmf.append(A1[a1k]["PM25"])
                pmc.append(A1[a1k]["PM10c"])
            if a1k and "低氮燃烧" in a1k:
                has_lnb_process = True
        elif cat == "除尘设施":
            a1k = PROCESS_TO_A1_DEDUST.get(p) if p else None
            row = A1.get(a1k) if a1k else None
            if rep is not None:
                pmf.append(min(rep, 100.0))
                pmc.append(min(rep, 100.0))
            elif row is not None:
                pmf.append(row["PM25"])
                pmc.append(row["PM10c"])
            else:
                notes.append((cat, proc))
            if row is not None and row.get("SO2"):
                so2.append(row["SO2"])
    return so2, nox, pmf, pmc, notes, has_lnb_process


def series(fracs):
    r = 0.0
    for x in fracs:
        r = 1 - (1 - r) * (1 - x)
    return r


