def build_components(dev):
    comps = []
    for slot, cid in (("一", "F1"), ("二", "F2")):
        fuel = g102(dev, "燃料%s类型" % slot)
        unit = g102(dev, "燃料%s消耗量单位" % slot)
        val = num(g102(dev, "燃料%s消耗量" % slot))
        if fuel is None or str(fuel).strip() == "":
            continue
        comps.append({"cid": cid, "fuel": str(fuel).strip(), "unit": unit if unit else "",
                      "value": val, "src": "fuel%s" % slot})
    oth = num(g102(dev, "其他燃料消耗总量（吨标准煤）"))
    if oth is not None and oth > 0:
        dup = any(c["unit"] == "吨标准煤" and c["value"] is not None and abs(c["value"] - oth) < 1e-9 for c in comps)
        if not dup:
            comps.append({"cid": "F3", "fuel": "其他燃料（未分类）", "unit": "吨标准煤", "value": oth, "src": "other_tce"})
    return comps


def calc_source(dev, gygl):
    comps = build_components(dev)

    so2_e, nox_e, pmf_e, pmc_e, fac_notes, has_lnb_proc = facility_contributions(gygl)
    # 低氮燃烧技术（设备填报"是"），若脱硝设施工艺已含低氮燃烧则不重复计入
    if g102_lnb(dev) == "是" and not has_lnb_proc:
        nox_e.append(22.0)

    eta = {
        "SO2": series([x / 100.0 for x in so2_e]),
        "NOx": series([x / 100.0 for x in nox_e]),
        "CO": 0.0, "VOC": 0.0, "NH3": 0.0,
        "PM2.5": series([x / 100.0 for x in pmf_e]),
        "PM10_fine": series([x / 100.0 for x in pmf_e]),
        "PM10_coarse": series([x / 100.0 for x in pmc_e]),
        "BC": series([x / 100.0 for x in pmf_e]),
        "OC": series([x / 100.0 for x in pmf_e]),
    }
    ctrl_desc = {
        "SO2": "脱硫设施" if so2_e else "无治理",
        "NOx": "脱硝设施/低氮燃烧" if nox_e else "无治理",
        "CO": "无治理", "VOC": "无治理（燃烧烟气无末端治理，标准§8.2.1.2-5）", "NH3": "无治理",
        "PM2.5": "除尘设施" if pmf_e else "无治理",
        "PM10": "除尘设施" if pmf_e else "无治理",
        "BC": "除尘设施" if pmf_e else "无治理",
        "OC": "除尘设施" if pmf_e else "无治理",
    }

    # 结果容器：每污染物 {computed, gen, emis, activity[], params[], controls[], reasons[]}
    res = {}
    for p in POLLUTANTS:
        res[p] = {"computed": False, "gen": 0.0, "emis": 0.0,
                  "activity": [], "params": [], "controls": [], "reasons": []}

    if not comps:
        for p in POLLUTANTS:
            res[p]["reasons"].append(("NO_ACTIVITY", "设备行无任何燃料消耗量信息"))
    else:
        for comp in comps:
            cid = comp["cid"]
            fuel = comp["fuel"]
            act = {"component_id": cid, "value": comp["value"], "unit": comp["unit"]}
            for p in POLLUTANTS:
                res[p]["activity"].append(act)

            if comp["value"] is None:
                for p in POLLUTANTS:
                    res[p]["reasons"].append(("NO_ACTIVITY", "组件%s(%s)有燃料类型但无消耗量" % (cid, fuel)))
                continue
            if comp["value"] < 0:
                for p in POLLUTANTS:
                    res[p]["reasons"].append(("NEGATIVE_ACTIVITY", "组件%s活动水平为负" % cid))
                continue

            e7f = FUEL_TO_E7.get(fuel)
            if e7f is None:
                if fuel in NONFOSSIL_FUELS:
                    reason = "NO_EF_NONFOSSIL"
                elif fuel in ("其他燃料", "其他燃料（未分类）"):
                    reason = "NO_EF_UNSPECIFIED_FUEL"
                else:
                    reason = "NO_EF_FUEL_NOT_IN_TABLE"
                for p in POLLUTANTS:
                    res[p]["reasons"].append((reason, "组件%s(%s)在表E.7/E.2中无产生系数" % (cid, fuel)))
                continue

            is_gas = comp["unit"] in GAS_UNITS
            tech = None
            if e7f == "煤炭":
                tech = COMBUSTION_TO_TECH.get(g102(dev, "工业锅炉燃烧方式"))
                if tech is None:
                    for p in POLLUTANTS:
                        res[p]["reasons"].append(
                            ("COAL_TECH_UNKNOWN", "组件%s燃煤燃烧方式'%s'无法映射表E.7煤炭燃烧技术" % (cid, g102(dev, "工业锅炉燃烧方式"))))
                    continue

            if e7f == "煤炭":
                tech_key = tech
            elif e7f == "焦炭":
                tech_key = "不分技术"
            elif e7f in GAS_FUEL_KEYS or e7f in LIQUID_GAS_KEYS:
                tech_key = "燃气锅炉"
            else:
                tech_key = "燃油锅炉"
            row = EF_E7[e7f][tech_key]

            if is_gas:
                a_conv = comp["value"] * 1e4
            else:
                a_conv = comp["value"] * 1e3
            ef_unit = "g/m3" if is_gas else "g/kg"

            slot = "一" if cid == "F1" else "二"
            s_val = num(g102(dev, "燃料%s平均收到基含硫量" % slot))
            ash = num(g102(dev, "燃料%s平均收到基灰分（%%）" % slot))

            # 物料衡算项
            mb_ef = {}
            mb_missing = {}
            if e7f == "煤炭":
                prm = COAL_PARAM[tech]
                if s_val is None:
                    mb_missing["SO2"] = "含硫量缺失"
                else:
                    mb_ef["SO2"] = 20.0 * s_val * (1 - prm["sr"])
                if ash is None:
                    mb_missing["PM25"] = "灰分缺失"
                    mb_missing["PM10"] = "灰分缺失"
                    mb_missing["BC"] = "灰分缺失"
                    mb_missing["OC"] = "灰分缺失"
                else:
                    ef_pm25 = 10.0 * ash * (1 - prm["ar"]) * prm["fPM25"]
                    mb_ef["PM25"] = ef_pm25
                    mb_ef["PM10"] = 10.0 * ash * (1 - prm["ar"]) * prm["fPM10"]
                    mb_ef["BC"] = ef_pm25 * prm["fBC"]
                    mb_ef["OC"] = ef_pm25 * prm["fOC"]
            elif e7f == "焦炭":
                # 表E.7焦炭SO2/PM为物料衡算，但基102未单独填报焦炭含硫量/灰分
                for k in ["SO2", "PM25", "PM10", "BC", "OC"]:
                    mb_missing[k] = "焦炭含硫量/灰分未填报，无法物料衡算"

            def add_component_pollutant(p, pk, ef_val, mb):
                gen = a_conv * ef_val * 1e-6
                res[p]["computed"] = True
                if p == "PM10":
                    gen25 = a_conv * mb_ef["PM25"] * 1e-6
                    emis = gen25 * (1 - eta["PM10_fine"]) + (gen - gen25) * (1 - eta["PM10_coarse"])
                    res[p]["gen"] += gen
                    res[p]["emis"] += emis
                    ctrl = {"component_id": cid, "method": ctrl_desc["PM10"], "efficiency": None,
                            "fine_efficiency": round(eta["PM10_fine"] * 100, 4),
                            "coarse_efficiency": round(eta["PM10_coarse"] * 100, 4)}
                else:
                    res[p]["gen"] += gen
                    res[p]["emis"] += gen * (1 - eta[p])
                    ctrl = {"component_id": cid, "method": ctrl_desc[p],
                            "efficiency": round(eta[p] * 100, 4), "fine_efficiency": None, "coarse_efficiency": None}
                res[p]["params"].append({"component_id": cid, "parameter_id": "EF_%s" % pk,
                                         "mode": "computed" if mb else "from_standard",
                                         "value": round(ef_val, 6), "unit": ef_unit})
                res[p]["controls"].append(ctrl)

            for pk, p in [("SO2", "SO2"), ("PM25", "PM2.5"), ("PM10", "PM10"), ("BC", "BC"), ("OC", "OC")]:
                if pk in mb_missing:
                    res[p]["reasons"].append(("MATERIAL_BALANCE_PARAM_MISSING",
                                              "组件%s %s物料衡算参数不足：%s" % (cid, POLLUTANT_CN[p], mb_missing[pk])))
                elif pk in mb_ef:
                    add_component_pollutant(p, pk, mb_ef[pk], True)
                else:
                    add_component_pollutant(p, pk, row[pk], False)

            for pk, p in [("CO", "CO"), ("NOx", "NOx"), ("VOC", "VOC")]:
                add_component_pollutant(p, pk, row[pk], False)

    # NH3：标准无固定燃烧NH3产生系数
    for p in ["NH3"]:
        if not res[p]["computed"]:
            res[p]["reasons"].append(("NO_EF_NH3", "T/CSES 144-2024未提供固定燃烧NH3产生系数"))

    return res, comps, fac_notes


