def fmt_num(v):
    if v is None:
        return ""
    if isinstance(v, float):
        s = ("%.6f" % v).rstrip("0").rstrip(".")
        return s if s not in ("", "-") else "0"
    return str(v)


def std_ref(p):
    base = "T/CSES 144-2024"
    if p == "NH3":
        return "%s 表E.7（固定燃烧无NH3列）" % base
    if p in ("SO2", "PM2.5", "PM10", "BC", "OC"):
        return "%s 表E.7；公式(3)-(6)；附录C 表C.1-C.3" % base
    return "%s 表E.7；公式(2)" % base


